class Solution:
    def countAndSay(self, n: int) -> str:
        term = "1"
        for _ in range(n - 1):
            parts = []
            i = 0
            while i < len(term):
                j = i + 1
                while j < len(term) and term[j] == term[i]:
                    j += 1
                parts.extend((str(j - i), term[i]))
                i = j
            term = "".join(parts)
        return term

